$(document).ready(function(e){if($(".selectJS").length){function t(e){if(!e.id)return e.text;var t=$(e.element).data("flag"),a=$('<span><img src="'+t+'" class="flag-img" style="width: 30px; height: 30px; margin-right: 10px; border-radius: 100%" />'+e.text+"</span>");return a}$(".selectJS").select2({placeholder:"Search for country",templateResult:t,tag:!0,templateSelection:t,width:"100%"})}});